#include <iiMultimodalAgent/agent/McpConnections.h>
#include <iiMultimodalAgent/agent/Engine.h>

auto registry = std::make_shared<iiMultimodalAgent::agent::ToolRegistry>();
iiMultimodalAgent::agent::McpConnectionOptions options;
options.workingDirectory = workspace;
options.configFiles = {configPath};
auto connections = std::make_shared<iiMultimodalAgent::agent::McpConnections>(registry, options);
// 같은 registry를 Engine 또는 agent::Api에 전달한다.
// ApiOptions::mcp = connections이면 인증된 agent.mcp.status에서 상태를 조회한다.
